// Reads the body and answers one request.
function serve(req, res, max, control) {
  {
    const chunks = [];
    let size = 0;
    let held = 0;
    let rejected = false;
    const release = () => {
      buffered -= held;
      held = 0;
    };
    req.on('data', (c) => {
      if (rejected) return; // drain and discard the rest so the client can read the answer
      size += c.length;
      if (size > max || buffered + c.length > BUFFERED_BUDGET) {
        rejected = true;
        chunks.length = 0;
        release();
        return;
      }
      chunks.push(c);
      held += c.length;
      buffered += c.length;
    });
    req.on('error', release);
    req.on('close', release);
    req.on('end', () => {
      if (rejected) {
        send(res, tooLarge(max));
        return;
      }
      let url;
      try {
        url = new URL(req.url, 'http://localhost');
      } catch (e) {
        release();
        send(res, errorResponse(404, 'not_found', 'bad request target'));
        return;
      }
      const raw = Buffer.concat(chunks);
      chunks.length = 0;
      const ctx = { req, method: req.method, path: url.pathname, query: url.searchParams, raw };
      (control ? runInLane(() => handle(ctx)) : handle(ctx)).then((out) => send(res, out), (e) => {
        console.error('unhandled', e);
        send(res, errorResponse(500, 'internal_error', 'internal error'));
      }).finally(release);
    });
  }
}

